                    'league_id' => $leagueIds[$row['league_slug']],
                    'home_team_id' => $teamIds[$row['home_code']],
                    'away_team_id' => $teamIds[$row['away_code']],
                    'matchday' => $row['matchday'],
                ],
                [
                    'kickoff_at' => \Carbon\Carbon::parse($row['kickoff_at']),
                    'venue' => $row['venue'],
                    'home_preview_note' => $row['home_preview_note'],
                    'away_preview_note' => $row['away_preview_note'],
                    'status' => $row['status'],
                    'home_score' => $row['home_score'],
                    'away_score' => $row['away_score'],
                    'match_report' => $row['match_report'],
                    'stats' => $row['stats'],
                ]
            );
        }
    }
}
